const ALLOWED_RESULT_FIELDS = [
  'job_id', 'intake_source', 'source_reference', 'source_row_ref', 'row_number',
  'state', 'status', 'authentication_success', 'user_session_available',
  'member_command_found', 'get_member_found', 'submitted_member_no_status',
  'normalized_member_no_length', 'member_exists', 'member_found_by',
  'manual_review_required', 'warning_count', 'error_code', 'consent_status',
  'pdpa_status', 'attempt', 'dry_run_only', 'final_write_automation',
  'result_created_at', 'result_applied_at'
];
const FORBIDDEN_RESULT_FIELDS = [
  'member_no', 'member_number', 'normalized_member_no', 'decoded_member_no',
  'raw_member_no', 'submitted_member_no_base64_utf8', 'payload_hash', 'intake_id',
  'name', 'full_name', 'email', 'email_address', 'phone', 'mobile',
  'raw_phone_number', 'dob', 'birthday', 'birthday_month', 'address', 'server',
  'database', 'user', 'password', 'connection_string', 'stderr', 'stdout',
  'token', 'secret', 'sheet_id', 'sheet_url', 'document_id', 'command',
  'command_text', 'payload'
];
const ALLOWED_MEMBER_STATUS_LABELS = [
  null, 'canonical_65_mobile', 'already_65_mobile', 'manual_review', 'invalid_too_long'
];
const SUCCESS_STATES = ['EXISTING_MEMBER_REVIEW', 'MANUAL_REVIEW_REQUIRED', 'READY_FOR_CREATE_REVIEW'];
const ALL_STATES = SUCCESS_STATES.concat(['LOOKUP_ERROR_REVIEW']);
const CANONICAL_SOURCE_LABEL = 'google_sheets_uat_gate4a';
const CANONICAL_JOB_ID_RE = /^gate4a_fnv1a_[0-9a-f]{8}$/;
const SAFE_ERROR_CODE_RE = /^[a-z0-9_]{1,64}$/;
const SAFE_TIMESTAMP_RE = /^[0-9T:+.Z-]{1,64}$/;
const SAFE_ID_RE = /^[A-Za-z0-9_.:-]{1,128}$/;

const isBool = (value) => typeof value === 'boolean';
const isInt = (value) => Number.isInteger(value) && typeof value === 'number';

const items = $input.all();
if (items.length !== 1) throw new Error('gate5a_expected_one_extracted_text_item');
const text = items[0].json.data;
if (typeof text !== 'string' || !text.trim()) throw new Error('gate5a_result_copy_empty');
const lines = text.split(/\r?\n/).filter((line) => line.trim());
if (lines.length !== 1) throw new Error('gate5a_result_copy_must_contain_exactly_one_row');

let result;
try {
  result = JSON.parse(lines[0]);
} catch (error) {
  throw new Error('gate5a_result_copy_malformed_json');
}
if (!result || typeof result !== 'object' || Array.isArray(result)) {
  throw new Error('gate5a_result_copy_not_a_single_object');
}

const keys = Object.keys(result);
if (keys.some((key) => FORBIDDEN_RESULT_FIELDS.includes(key))) {
  throw new Error('gate5a_result_forbidden_field_present');
}
if (ALLOWED_RESULT_FIELDS.some((field) => !keys.includes(field))) {
  throw new Error('gate5a_result_required_field_missing');
}
if (keys.some((key) => !ALLOWED_RESULT_FIELDS.includes(key))) {
  throw new Error('gate5a_result_unexpected_field_present');
}

const invalid = () => new Error('gate5a_result_field_types_invalid');
if (typeof result.job_id !== 'string' || !SAFE_ID_RE.test(result.job_id) || !CANONICAL_JOB_ID_RE.test(result.job_id)) throw invalid();
if (result.intake_source !== CANONICAL_SOURCE_LABEL) throw invalid();
if (result.source_reference !== CANONICAL_SOURCE_LABEL) throw invalid();
if (!isInt(result.row_number) || result.row_number < 1) throw invalid();
if (result.source_row_ref !== `row_${result.row_number}`) throw invalid();
if (!ALL_STATES.includes(result.state)) throw new Error('gate5a_result_state_unrecognised');
if (!['ok', 'error', 'refused'].includes(result.status)) throw new Error('gate5a_result_status_unrecognised');
for (const flag of ['authentication_success', 'user_session_available', 'member_command_found', 'get_member_found', 'member_exists', 'manual_review_required']) {
  if (!isBool(result[flag])) throw invalid();
}
if (!ALLOWED_MEMBER_STATUS_LABELS.includes(result.submitted_member_no_status)) throw invalid();
if (!isInt(result.normalized_member_no_length) || result.normalized_member_no_length < 0) throw invalid();
if (result.member_found_by !== null && (typeof result.member_found_by !== 'string' || !SAFE_ID_RE.test(result.member_found_by))) throw invalid();
if (!isInt(result.warning_count) || result.warning_count < 0) throw invalid();
if (result.error_code !== null && (typeof result.error_code !== 'string' || !SAFE_ERROR_CODE_RE.test(result.error_code))) throw invalid();
if (result.consent_status !== 'marketing_consent_not_queued') throw invalid();
if (result.pdpa_status !== 'yes') throw invalid();
if (result.attempt !== 0 || !isInt(result.attempt)) throw invalid();
if (typeof result.result_created_at !== 'string' || !SAFE_TIMESTAMP_RE.test(result.result_created_at)) throw invalid();
if (result.dry_run_only !== true) throw new Error('gate5a_result_dry_run_only_must_be_true');
if (result.final_write_automation !== false) throw new Error('gate5a_result_final_write_automation_must_be_false');
if (result.result_applied_at !== null) throw new Error('gate5a_result_applied_at_must_be_null');

// Recompute the review state with the fixed worker precedence; never trust the string.
let computedState;
if (result.status !== 'ok') computedState = 'LOOKUP_ERROR_REVIEW';
else if (result.manual_review_required === true || result.warning_count > 0) computedState = 'MANUAL_REVIEW_REQUIRED';
else if (result.member_exists === true) computedState = 'EXISTING_MEMBER_REVIEW';
else computedState = 'READY_FOR_CREATE_REVIEW';
if (computedState !== result.state) throw new Error('gate5a_result_state_inconsistent');
if (result.status === 'ok') {
  if (result.error_code !== null) throw new Error('gate5a_result_state_inconsistent');
  for (const flag of ['authentication_success', 'user_session_available', 'member_command_found', 'get_member_found']) {
    if (result[flag] !== true) throw new Error('gate5a_result_state_inconsistent');
  }
} else {
  if (result.error_code === null) throw new Error('gate5a_result_state_inconsistent');
}

return [{ json: result }];

const SOURCE_LABEL = 'google_sheets_uat_gate4a';
const FIELD_ALIASES = {
  name: ['Full Name', 'Name'],
  memberNo: ['AutoCount MemberNo', 'Phone/Member Number', 'Phone Member Number', 'Phone Number', 'Member Number', 'Submitted Member Number', 'Submitted Member No', 'Mobile Number'],
  email: ['Email Address', 'Email'],
  birthdayMonth: ['Birthday Month', 'Birthday', 'Date of Birth', 'DOB'],
  marketingConsent: ['Marketing Consent', 'consent_status', 'Consent Status'],
  pdpa: ['PDPA Acknowledged', 'PDPA', 'PDPA Status'],
  rowNumber: ['row_number', 'Row Number', 'RowNumber']
};
const MONTH_NAMES = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
const REQUIRED_REVIEW_COLUMNS = [
  'uat_lookup_job_id', 'uat_lookup_state', 'uat_lookup_status',
  'uat_lookup_error_code', 'uat_lookup_warning_count', 'uat_lookup_attempt',
  'uat_lookup_completed_at', 'reviewer_status'
];

const result = $('Validate Copied Sanitized Result Strictly').first().json;

const items = $input.all();
if (items.length !== 1) throw new Error('gate5a_requires_exactly_one_approved_source_row');
const row = items[0].json;

for (const column of REQUIRED_REVIEW_COLUMNS) {
  if (!Object.prototype.hasOwnProperty.call(row, column)) {
    throw new Error('gate5a_required_review_column_missing_add_review_columns_before_run');
  }
}

// Rebuild the canonical Gate 4A queue identity from raw form values. Raw values stay
// in this execution only: they are never returned, logged, or written anywhere.
const pick = (aliases) => {
  for (const key of aliases) {
    if (Object.prototype.hasOwnProperty.call(row, key)) return row[key];
  }
  return undefined;
};
const clean = (value) => String(value ?? '').trim();

const requiredName = clean(pick(FIELD_ALIASES.name));
const submittedMemberNo = clean(pick(FIELD_ALIASES.memberNo));
const requiredEmail = clean(pick(FIELD_ALIASES.email));
const birthdayMonthRaw = clean(pick(FIELD_ALIASES.birthdayMonth));
const marketingConsentRaw = clean(pick(FIELD_ALIASES.marketingConsent));
const pdpaRaw = clean(pick(FIELD_ALIASES.pdpa));
const rowNumber = Number(pick(FIELD_ALIASES.rowNumber));

if (!requiredName) throw new Error('gate5a_full_name_required');
if (!requiredEmail) throw new Error('gate5a_email_address_required');
if (!MONTH_NAMES.includes(birthdayMonthRaw.toLowerCase())) throw new Error('gate5a_birthday_month_must_be_valid_month_name');
if (!/^[0-9]{6,20}$/.test(submittedMemberNo)) throw new Error('gate5a_autocount_member_no_must_be_6_to_20_digits');
if (/imported/i.test(pdpaRaw)) throw new Error('gate5a_imported_pdpa_marker_blocked');
if (pdpaRaw.toLowerCase() !== 'yes') throw new Error('gate5a_pdpa_must_be_yes');
if (!Number.isInteger(rowNumber) || rowNumber < 1) throw new Error('gate5a_safe_row_number_required');

const dummySourceText = [requiredName, submittedMemberNo, requiredEmail, birthdayMonthRaw, marketingConsentRaw, pdpaRaw].join(' ').toLowerCase();
if (/\b(dummy|fixture|placeholder|rehearsal|sample|synthetic)\b/.test(dummySourceText)) {
  throw new Error('gate5a_source_row_must_be_real_non_dummy');
}

const submittedMemberNoBase64 = Buffer.from(submittedMemberNo, 'utf8').toString('base64');
const sourceRowRef = `row_${rowNumber}`;
const intakeId = `gate4a_${sourceRowRef}`;

const fnv1a = (text) => {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
};

const payloadHash = `fnv1a_${fnv1a(JSON.stringify({
  intake_source: SOURCE_LABEL,
  source_reference: SOURCE_LABEL,
  source_row_ref: sourceRowRef,
  row_number: rowNumber,
  intake_id: intakeId,
  state: 'PENDING_LOOKUP',
  submitted_member_no_base64_utf8: submittedMemberNoBase64,
  pdpa_status: 'yes'
}))}`;
const expectedJobId = `gate4a_${payloadHash}`;

// Match every safe identity field shared by the durable result and the canonical
// queue contract. A row number alone is never sufficient.
const identityMatches = (
  result.job_id === expectedJobId
  && result.intake_source === SOURCE_LABEL
  && result.source_reference === SOURCE_LABEL
  && result.source_row_ref === sourceRowRef
  && result.row_number === rowNumber
  && result.consent_status === 'marketing_consent_not_queued'
  && result.pdpa_status === 'yes'
  && result.attempt === 0
);
if (!identityMatches) throw new Error('gate5a_result_does_not_match_approved_source_row');

// Strict mapping precedence, recomputed here as well.
let mappedState;
if (result.status !== 'ok') mappedState = 'LOOKUP_ERROR_REVIEW';
else if (result.manual_review_required === true || result.warning_count > 0) mappedState = 'MANUAL_REVIEW_REQUIRED';
else if (result.member_exists === true) mappedState = 'EXISTING_MEMBER_REVIEW';
else mappedState = 'READY_FOR_CREATE_REVIEW';
if (mappedState !== result.state) throw new Error('gate5a_result_state_inconsistent');

// Idempotency: the row must be fully pre-mapping blank (apply) or exactly and
// completely mapped with the same values (already_applied). Anything else refuses.
const cell = (name) => String(row[name] ?? '').trim();
const wouldWrite = {
  uat_lookup_job_id: result.job_id,
  uat_lookup_state: mappedState,
  uat_lookup_status: result.status,
  uat_lookup_error_code: result.error_code === null ? '' : String(result.error_code),
  uat_lookup_warning_count: String(result.warning_count),
  uat_lookup_attempt: String(result.attempt),
  uat_lookup_completed_at: result.result_created_at,
  reviewer_status: 'UNREVIEWED'
};
const existingBlank = REQUIRED_REVIEW_COLUMNS.every((column) => cell(column) === '');
const existingExact = REQUIRED_REVIEW_COLUMNS.every((column) => cell(column) === String(wouldWrite[column]).trim());

let decision;
if (existingBlank) decision = 'apply';
else if (existingExact) decision = 'already_applied';
else throw new Error('gate5a_conflicting_prior_mapping_refused');

return [{
  json: {
    gate5a_decision: decision,
    gate5a_mapped_state: mappedState,
    row_number: rowNumber,
    uat_lookup_job_id: wouldWrite.uat_lookup_job_id,
    uat_lookup_state: wouldWrite.uat_lookup_state,
    uat_lookup_status: wouldWrite.uat_lookup_status,
    uat_lookup_error_code: wouldWrite.uat_lookup_error_code,
    uat_lookup_warning_count: wouldWrite.uat_lookup_warning_count,
    uat_lookup_attempt: wouldWrite.uat_lookup_attempt,
    uat_lookup_completed_at: wouldWrite.uat_lookup_completed_at,
    reviewer_status: wouldWrite.reviewer_status
  }
}];

const SOURCE_LABEL = 'google_sheets_uat_gate4a';
const FIELD_ALIASES = {
  name: ['Full Name', 'Name'],
  memberNo: ['AutoCount MemberNo', 'Phone/Member Number', 'Phone Member Number', 'Phone Number', 'Member Number', 'Submitted Member Number', 'Submitted Member No', 'Mobile Number'],
  email: ['Email Address', 'Email'],
  birthdayMonth: ['Birthday Month', 'Birthday', 'Date of Birth', 'DOB'],
  pdpa: ['PDPA Acknowledged', 'PDPA', 'PDPA Status'],
  rowNumber: ['row_number', 'Row Number', 'RowNumber']
};
const REQUIRED_REVIEW_COLUMNS = [
  'uat_lookup_job_id', 'uat_lookup_state', 'uat_lookup_status',
  'uat_lookup_error_code', 'uat_lookup_warning_count', 'uat_lookup_attempt',
  'uat_lookup_completed_at', 'reviewer_status'
];

const result = $('Validate Copied Sanitized Result Strictly').first().json;
const intended = $('Verify Identity And Decide Mapping').first().json;
if (intended.gate5a_decision !== 'apply') {
  throw new Error('gate5a_postwrite_unexpected_branch');
}

// The read-back must return exactly one approved row; zero, duplicates, or a
// filter drift after the update are terminal and never become success evidence.
const items = $input.all();
if (items.length !== 1) {
  throw new Error('gate5a_postwrite_requires_exactly_one_approved_source_row');
}
const row = items[0].json;

// Rebuild the full canonical Gate 4A identity from the persisted row and require
// it to still match the sanitized result. Raw values stay in execution memory
// only and are never echoed into errors or evidence. Any derivation failure or
// mismatch (including row reorder/drift, which changes the recomputed identity)
// is a single sanitized terminal error.
const identityFailure = () => new Error('gate5a_postwrite_identity_verification_failed');
const pick = (aliases) => {
  for (const key of aliases) {
    if (Object.prototype.hasOwnProperty.call(row, key)) return row[key];
  }
  return undefined;
};
const clean = (value) => String(value ?? '').trim();

const submittedMemberNo = clean(pick(FIELD_ALIASES.memberNo));
const pdpaRaw = clean(pick(FIELD_ALIASES.pdpa));
const rowNumber = Number(pick(FIELD_ALIASES.rowNumber));
if (!/^[0-9]{6,20}$/.test(submittedMemberNo)) throw identityFailure();
if (pdpaRaw.toLowerCase() !== 'yes') throw identityFailure();
if (!Number.isInteger(rowNumber) || rowNumber < 1) throw identityFailure();

const submittedMemberNoBase64 = Buffer.from(submittedMemberNo, 'utf8').toString('base64');
const sourceRowRef = `row_${rowNumber}`;
const intakeId = `gate4a_${sourceRowRef}`;
const fnv1a = (text) => {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
};
const payloadHash = `fnv1a_${fnv1a(JSON.stringify({
  intake_source: SOURCE_LABEL,
  source_reference: SOURCE_LABEL,
  source_row_ref: sourceRowRef,
  row_number: rowNumber,
  intake_id: intakeId,
  state: 'PENDING_LOOKUP',
  submitted_member_no_base64_utf8: submittedMemberNoBase64,
  pdpa_status: 'yes'
}))}`;
const expectedJobId = `gate4a_${payloadHash}`;
const identityMatches = (
  result.job_id === expectedJobId
  && result.intake_source === SOURCE_LABEL
  && result.source_reference === SOURCE_LABEL
  && result.source_row_ref === sourceRowRef
  && result.row_number === rowNumber
  && result.consent_status === 'marketing_consent_not_queued'
  && result.pdpa_status === 'yes'
  && result.attempt === 0
);
if (!identityMatches) throw identityFailure();

// Every controlled review/status field must hold exactly the intended persisted
// value. Missing, blank, partial, extra-state, or conflicting values are terminal.
const cell = (name) => String(row[name] ?? '').trim();
for (const column of REQUIRED_REVIEW_COLUMNS) {
  if (!Object.prototype.hasOwnProperty.call(row, column)) {
    throw new Error('gate5a_postwrite_persisted_state_mismatch');
  }
  if (cell(column) !== String(intended[column]).trim()) {
    throw new Error('gate5a_postwrite_persisted_state_mismatch');
  }
}
if (cell('reviewer_status') !== 'UNREVIEWED') {
  throw new Error('gate5a_postwrite_persisted_state_mismatch');
}

return [{
  json: {
    gate5a_persisted_verified: true,
    gate5a_decision: 'apply',
    gate5a_mapped_state: intended.gate5a_mapped_state
  }
}];

const verify = $('Verify Identity And Decide Mapping').first().json;
const decision = verify.gate5a_decision;
const mappedState = verify.gate5a_mapped_state;
if (decision !== 'apply' && decision !== 'already_applied') {
  throw new Error('gate5a_unexpected_mapping_decision');
}
const REVIEW_STATES = ['LOOKUP_ERROR_REVIEW', 'MANUAL_REVIEW_REQUIRED', 'EXISTING_MEMBER_REVIEW', 'READY_FOR_CREATE_REVIEW'];
if (!REVIEW_STATES.includes(mappedState)) {
  throw new Error('gate5a_unexpected_mapped_state');
}
if (decision === 'apply') {
  // Success evidence is only reachable through the post-write read-back branch:
  // referencing the verification node fails when it did not execute, and its
  // output must confirm the exact persisted state for the same mapped state.
  const persisted = $('Verify Persisted Mapping Strictly').first().json;
  if (persisted.gate5a_persisted_verified !== true
    || persisted.gate5a_decision !== 'apply'
    || persisted.gate5a_mapped_state !== mappedState) {
    throw new Error('gate5a_success_evidence_requires_persisted_verification');
  }
}
return [{
  json: {
    status: 'ok',
    gate: 'gate5a_manual_inactive_n8n_result_mapping',
    runtime_location: 'local_operator_pc_non_ac2_n8n_stack',
    execution_mode: 'manual_inactive_single_result_review_mapping_only',
    input_result_row_count: 1,
    result_schema_valid_count: 1,
    source_rows_read_count: 1,
    source_row_match_count: 1,
    mapping_attempt_count: 1,
    mapping_success_count: decision === 'apply' ? 1 : 0,
    mapping_already_applied_count: decision === 'already_applied' ? 1 : 0,
    mapping_error_count: 0,
    mapped_lookup_error_review_count: mappedState === 'LOOKUP_ERROR_REVIEW' ? 1 : 0,
    mapped_manual_review_required_count: mappedState === 'MANUAL_REVIEW_REQUIRED' ? 1 : 0,
    mapped_existing_member_review_count: mappedState === 'EXISTING_MEMBER_REVIEW' ? 1 : 0,
    mapped_ready_for_create_review_count: mappedState === 'READY_FOR_CREATE_REVIEW' ? 1 : 0,
    reviewer_status_unreviewed_count: 1,
    original_gate4_artifacts_modified: false,
    autocount_lookup_invoked: false,
    member_create_or_update_invoked: false,
    autocount_write_attempted: false,
    direct_sql_write_attempted: false,
    workflow_activation: 'inactive',
    scheduler_enabled: false,
    public_inbound_to_ac2_host: false,
    final_write_automation: false,
    no_row_values_printed: true
  }
}];
